script:
// Line drawing on the DualPanto (prototype): draw lines with Me, feel them with It.
//
// Me draws: say "draw", move Me, say "stop" – the path becomes a line.
// It traces: move It with your other hand; it snaps onto the lines and follows them.
//
// Voice commands (say them any time):
//   "draw", "stop"   start a line, end it (also ends "show")
//   "show"           It moves along every line on its own
//   "undo"           removes the last line
//   "clear all"      removes every line
//
// The first run downloads the small on-device speech model (about 24 MB) and caches it.

void voice.prepareIntents();

levels.script:
// Level "Lines": vector drawing inside the frame.
// Me draws: say "draw", move Me, say "stop" – the path becomes a line.
// It traces: every line is a rail for It, so It snaps onto a line and follows it.
// A beep tells when It reaches a line, a lower one when it leaves it.

const MIN_STEP = 2;        // mm between recorded points
const SIMPLIFY = 1;        // mm a line may deviate from the drawn path
const MAX_POINTS = 24;     // per line, so a line stays a handful of packets on the device
const MIN_LENGTH = 6;      // mm; shorter strokes are dropped
const ON_LINE = 3;         // mm from a line counts as "on it"

let lines = [];            // { points, rail }
let stroke = null;         // points of the line being drawn, or null
let touring = false;       // It is moved by the program
let stopTour = false;

const pathLength = (pts) => pts.reduce((sum, p, i) => (i ? sum + distance(pts[i - 1], p) : 0), 0);

/** Distance from p to the segment a–b. */
function segmentDistance(p, a, b) {
  const dx = b.x - a.x, dy = b.y - a.y, len2 = dx * dx + dy * dy;
  const t = len2 ? Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2)) : 0;
  return Math.hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));
}

/** Ramer–Douglas–Peucker: keeps the points that matter for the shape. */
function simplify(pts, tolerance) {
  if (pts.length < 3) return pts;
  let worst = 0, index = 0;
  for (let i = 1; i < pts.length - 1; i++) {
    const d = segmentDistance(pts[i], pts[0], pts[pts.length - 1]);
    if (d > worst) [worst, index] = [d, i];
  }
  if (worst <= tolerance) return [pts[0], pts[pts.length - 1]];
  return [...simplify(pts.slice(0, index + 1), tolerance).slice(0, -1), ...simplify(pts.slice(index), tolerance)];
}

async function chirp(from, to) {
  await sound.beep(from, 50, { volume: 0.15 });
  sound.beep(to, 70, { volume: 0.15 });
}

// --- Me draws ---------------------------------------------------------------

function startDrawing() {
  if (stroke) return;
  stroke = [{ ...me.position }];
  chirp(500, 800);
}

function stopDrawing() {
  stopTour = true;
  if (!stroke) return;
  const drawn = stroke;
  stroke = null;
  chirp(800, 500);
  if (pathLength(drawn) < MIN_LENGTH) return speak("Too short.", { interrupt: true });
  let tolerance = SIMPLIFY, points = simplify(drawn, tolerance);
  while (points.length > MAX_POINTS) points = simplify(drawn, (tolerance *= 1.5));
  const rail = panto.rail(points, { strength: 4, handles: "it", name: `Line ${lines.length + 1}` });
  lines.push({ points, rail });
  speak(`Line ${lines.length}.`, { interrupt: true });
}

let sinceTick = 0;
me.onMove((p) => {
  if (!stroke) return;
  const last = stroke[stroke.length - 1];
  const step = distance(last, p);
  if (step < MIN_STEP) return;
  stroke.push({ x: p.x, y: p.y });
  sinceTick += step;
  if (sinceTick > 10) {
    sinceTick = 0;
    sound.beep(660, 20, { volume: 0.08 }); // the pen is moving
  }
});

// --- It traces --------------------------------------------------------------

const nearLine = (p) => lines.some(({ points }) => points.some((q, i) => i && segmentDistance(p, points[i - 1], q) < ON_LINE));

let onLine = false;
it.onMove((p) => {
  if (touring) return;
  const now = nearLine(p);
  if (now === onLine) return;
  onLine = now;
  sound.beep(now ? 880 : 330, 60, { volume: 0.2 });
});

/** "show": It moves along every line on its own. */
async function show() {
  if (touring) return;
  if (!lines.length) return speak("Nothing drawn yet.", { interrupt: true });
  touring = true;
  stopTour = false;
  await speak(lines.length === 1 ? "1 line." : `${lines.length} lines.`, { interrupt: true });
  for (const { points } of lines) {
    for (const q of points) {
      if (stopTour) break;
      await it.moveTo(q, { hold: true });
    }
    if (stopTour) break;
    sound.beep(880, 80, { volume: 0.15 });
    await wait(300);
  }
  it.free();
  touring = false;
}

function undo() {
  const line = lines.pop();
  if (!line) return speak("Nothing to undo.", { interrupt: true });
  line.rail.remove();
  speak(`Removed line ${lines.length + 1}.`, { interrupt: true });
}

function clearAll() {
  lines.forEach(({ rail }) => rail.remove());
  lines = [];
  speak("Cleared.", { interrupt: true });
}

// --- voice commands ---------------------------------------------------------
// "draw" and "stop" react while you are still speaking (interim result, strict threshold).

voice.intent("draw", { examples: ["draw", "pen down", "start drawing"], threshold: 0.9, onMatch: startDrawing });
voice.intent("stop", { examples: ["stop", "lift", "pen up", "stop drawing"], threshold: 0.9, onMatch: stopDrawing });
voice.intent("show", { examples: ["show", "show me", "trace the drawing", "show the lines"], interim: false, onMatch: show });
voice.intent("undo", { examples: ["undo", "remove the last line", "delete last line"], interim: false, onMatch: undo });
voice.intent("clear", { examples: ["clear all", "delete everything", "start over"], interim: false, onMatch: clearAll });
